// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address actor, uint64 dt) public {
        vm.assume(actor != address(0));
        dt = uint64(bound(dt, 1, 365 days));

        vm.deal(actor, 20 ether);

        uint256 prior = c.pastBlockTime();

        uint256 target = block.timestamp + uint256(dt);
        if (target <= prior) {
            target = prior + 1;
        }
        vm.warp(target);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "call to fallback failed");

        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}
